-- =====================================================================
-- Sistema de Almoxarifado - Projeto de Dados Final
-- SGBD: MySQL 8.0.16 ou superior (as restrições CHECK exigem essa versão)
-- Banco: almoxarifado
-- Executável a partir de um banco vazio. Reexecutável: recria as tabelas.
-- Gerado por scripts/gerar_massa_dados.py
-- =====================================================================

CREATE DATABASE IF NOT EXISTS almoxarifado CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE almoxarifado;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS movimentacoes;
DROP TABLE IF EXISTS bloqueios_material;
DROP TABLE IF EXISTS retiradas;
DROP TABLE IF EXISTS materiais;
DROP TABLE IF EXISTS funcionarios;
DROP TABLE IF EXISTS categorias;
DROP TABLE IF EXISTS setores;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE setores (
    id   INT AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(60) NOT NULL,
    CONSTRAINT uq_setores_nome UNIQUE (nome)
) ENGINE=InnoDB;

CREATE TABLE categorias (
    id        INT AUTO_INCREMENT PRIMARY KEY,
    nome      VARCHAR(60)  NOT NULL,
    descricao VARCHAR(150) NOT NULL,
    CONSTRAINT uq_categorias_nome UNIQUE (nome)
) ENGINE=InnoDB;

CREATE TABLE funcionarios (
    id            INT PRIMARY KEY,
    nome          VARCHAR(100) NOT NULL,
    setor_id      INT          NOT NULL,
    pode_retirar  TINYINT(1)   NOT NULL DEFAULT 1,
    data_admissao DATE         NOT NULL,
    CONSTRAINT fk_funcionarios_setor FOREIGN KEY (setor_id) REFERENCES setores (id),
    CONSTRAINT ck_funcionarios_pode CHECK (pode_retirar IN (0, 1))
) ENGINE=InnoDB;

CREATE TABLE materiais (
    codigo          VARCHAR(50)  PRIMARY KEY,
    nome            VARCHAR(100) NOT NULL,
    categoria_id    INT          NOT NULL,
    unidade         VARCHAR(10)  NOT NULL,
    quantidade      DOUBLE       NOT NULL DEFAULT 0,
    estoque_minimo  DOUBLE       NOT NULL DEFAULT 0,
    bloqueado       TINYINT(1)   NOT NULL DEFAULT 0,
    motivo_bloqueio VARCHAR(255) NOT NULL DEFAULT '',
    data_cadastro   DATETIME     NOT NULL,
    CONSTRAINT fk_materiais_categoria FOREIGN KEY (categoria_id) REFERENCES categorias (id),
    CONSTRAINT ck_materiais_quantidade CHECK (quantidade >= 0),
    CONSTRAINT ck_materiais_minimo CHECK (estoque_minimo >= 0),
    CONSTRAINT ck_materiais_bloqueado CHECK (bloqueado IN (0, 1))
) ENGINE=InnoDB;

CREATE TABLE bloqueios_material (
    id               INT AUTO_INCREMENT PRIMARY KEY,
    material_codigo  VARCHAR(50)  NOT NULL,
    motivo           VARCHAR(255) NOT NULL,
    data_bloqueio    DATETIME     NOT NULL,
    data_desbloqueio DATETIME     NULL,
    CONSTRAINT fk_bloqueios_material FOREIGN KEY (material_codigo) REFERENCES materiais (codigo),
    CONSTRAINT ck_bloqueios_periodo CHECK (data_desbloqueio IS NULL OR data_desbloqueio > data_bloqueio)
) ENGINE=InnoDB;

CREATE TABLE retiradas (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    funcionario_id  INT         NOT NULL,
    material_codigo VARCHAR(50) NOT NULL,
    quantidade      DOUBLE      NOT NULL,
    momento         DATETIME    NOT NULL,
    status          ENUM('CONCLUIDA', 'CANCELADA') NOT NULL DEFAULT 'CONCLUIDA',
    CONSTRAINT fk_retiradas_funcionario FOREIGN KEY (funcionario_id) REFERENCES funcionarios (id),
    CONSTRAINT fk_retiradas_material FOREIGN KEY (material_codigo) REFERENCES materiais (codigo),
    CONSTRAINT ck_retiradas_quantidade CHECK (quantidade > 0)
) ENGINE=InnoDB;

CREATE TABLE movimentacoes (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    material_codigo VARCHAR(50)  NOT NULL,
    tipo            ENUM('ENTRADA', 'SAIDA', 'ESTORNO') NOT NULL,
    quantidade      DOUBLE       NOT NULL,
    data_hora       DATETIME     NOT NULL,
    retirada_id     INT          NULL,
    observacao      VARCHAR(100) NOT NULL,
    CONSTRAINT fk_mov_material FOREIGN KEY (material_codigo) REFERENCES materiais (codigo),
    CONSTRAINT fk_mov_retirada FOREIGN KEY (retirada_id) REFERENCES retiradas (id),
    CONSTRAINT ck_mov_quantidade CHECK (quantidade > 0),
    CONSTRAINT ck_mov_retirada CHECK ((tipo = 'ENTRADA' AND retirada_id IS NULL)
                                   OR (tipo <> 'ENTRADA' AND retirada_id IS NOT NULL))
) ENGINE=InnoDB;

CREATE INDEX idx_retiradas_momento ON retiradas (momento);
CREATE INDEX idx_retiradas_funcionario ON retiradas (funcionario_id);
CREATE INDEX idx_retiradas_material ON retiradas (material_codigo);
CREATE INDEX idx_mov_material_data ON movimentacoes (material_codigo, data_hora);

